//! Pinned Plonky3 Poseidon2-M31 width-16 permutation.
//!
//! Parameters and constants are copied from `p3-mersenne-31 = 0.6.1`:
//! width 16, alpha 5, 8 full rounds (4+4), 14 partial rounds. The constants
//! were generated by Plonky3's Grain-LFSR script with
//! `(field_type=1, n=31, t=16, R_F=8, R_P=14)`. Unit tests include the
//! upstream KAT and differential checks against the pinned crate.

use aspis_core::field::M31;

pub const POSEIDON2_WIDTH: usize = 16;
pub const RATE: usize = 8;
pub const DIGEST_ELEMS: usize = 8;
pub type Digest = [M31; DIGEST_ELEMS];

